package com.chk.agentbrowser;

import android.app.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.json.*;

/** Track/clip controls edit a private candidate, committed once with the editor revision. */
final class StudioMixerSheet {
    private StudioMixerSheet(){}
    static void open(Activity a,JSONObject project,StudioCropSheet.Apply apply){try{
        LinkedHashSet<String> tracks=new LinkedHashSet<>();for(StudioMix.Source s:StudioMix.sources(project))tracks.add(s.track);List<String> labels=new ArrayList<>(),ids=new ArrayList<>();List<Boolean> type=new ArrayList<>();
        for(String id:tracks){labels.add("Piste · "+id);ids.add(id);type.add(true);}for(StudioMix.Source s:StudioMix.sources(project)){labels.add("Clip · "+s.clip.optString("path")+" · "+s.offset+" ms");ids.add(s.clip.getString("clip_id"));type.add(false);}labels.add("Ducking vocal et limiteur");
        new AgentDialog.Builder(a).setTitle("Mixage multipiste · niveaux indépendants").setItems(labels.toArray(new String[0]),(d,i)->{if(i==ids.size())ducking(a,project,apply);else edit(a,project,ids.get(i),type.get(i),apply);}).show();
    }catch(Exception e){error(a,e);}}
    static void edit(Activity a,JSONObject project,String id,boolean isTrack,StudioCropSheet.Apply apply){try{
        JSONObject copy=new JSONObject(project.toString());copy.put("audio_mix_version",2);if(!copy.has("mute_original"))copy.put("mute_original",false);JSONObject target=isTrack?StudioMix.settings(copy,id):StudioCommands.clip(copy,id);
        ScrollView scroll=new ScrollView(a);LinearLayout box=MobileUi.column(a);box.setPadding(20,10,20,10);scroll.addView(box);EditText percent=field(a,box,"Volume en % · 0 à 200",String.valueOf(target.optDouble("volume",1)*100)),db=field(a,box,"Gain en dB · silence : champ vide",target.optDouble("volume",1)==0?"":String.format(Locale.ROOT,"%.4f",StudioMix.db(target.optDouble("volume",1))));
        SeekBar slider=new SeekBar(a);slider.setMax(200);slider.setProgress((int)(target.optDouble("volume",1)*100));slider.setTag("studio_volume_slider");box.addView(slider);boolean[] updating={false};
        TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){}public void afterTextChanged(Editable e){if(updating[0])return;try{updating[0]=true;boolean fromPercent=e==percent.getEditableText();double linear=fromPercent?value(percent)/100:db.getText().toString().trim().isEmpty()?0:Math.pow(10,value(db)/20);if(linear<0||linear>2)return;slider.setProgress((int)Math.round(linear*100));if(fromPercent)db.setText(linear==0?"":String.format(Locale.ROOT,"%.4f",StudioMix.db(linear)));else percent.setText(String.format(Locale.ROOT,"%.4f",linear*100));}catch(Exception ignored){}finally{updating[0]=false;}}};percent.addTextChangedListener(watcher);db.addTextChangedListener(watcher);
        slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){if(!updating[0])percent.setText(String.valueOf(n));}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
        CheckBox mute=check(a,box,"Mute",target.optBoolean("mute")),solo=check(a,box,"Solo",target.optBoolean("solo"));EditText fadeIn=field(a,box,"Fondu d'entrée · ms",String.valueOf(target.optLong("fade_in_ms"))),fadeOut=field(a,box,"Fondu de sortie · ms",String.valueOf(target.optLong("fade_out_ms")));
        EditText offset=!isTrack&&!StudioCommands.isVideo(copy,target)?field(a,box,"Position du clip sur la timeline · ms",String.valueOf(target.optLong("offset_ms",audioOffset(copy,id)))):null;
        EditText trackId=!isTrack?fieldText(a,box,"Identifiant de piste",target.optString("track_id")):null;
        Spinner role=new Spinner(a);ArrayAdapter<String> options=new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"voice","music","ambience","fx"});role.setAdapter(options);String current=target.optString("role",isTrack&&id.equals("original")?"voice":"music");role.setSelection(Math.max(0,options.getPosition(current)));if(isTrack){box.addView(MobileUi.text(a,"Rôle de la piste pour le ducking",13,MobileUi.MUTED));box.addView(role);}
        Button keys=new Button(a);keys.setText("Keyframes de volume · "+(isTrack?"temps projet":"temps local du clip")+" en ms");box.addView(keys);keys.setOnClickListener(v->keyframes(a,target));
        Runnable collect=()->{try{double gain=value(percent)/100;if(Double.isNaN(gain)||Double.isInfinite(gain)||gain<0||gain>2)throw new Exception("Volume de 0 à 200 % requis");target.put("volume",gain).put("mute",mute.isChecked()).put("solo",solo.isChecked()).put("fade_in_ms",Math.round(value(fadeIn))).put("fade_out_ms",Math.round(value(fadeOut)));if(offset!=null)target.put("offset_ms",Math.round(value(offset)));if(trackId!=null){String track=trackId.getText().toString().trim();StudioMix.settings(copy,track);target.put("track_id",track);}if(isTrack)target.put("role",role.getSelectedItem().toString());StudioMix.validate(copy);}catch(Exception e){throw new IllegalArgumentException(e.getMessage());}};
        Button preview=new Button(a);preview.setText("Écouter le vrai mixage rendu");box.addView(preview);preview.setOnClickListener(v->{try{collect.run();listen(a,copy);}catch(Exception e){error(a,e);}});
        AlertDialog dialog=new AgentDialog.Builder(a).setTitle((isTrack?"Piste ":"Clip ")+id).setView(scroll).setNegativeButton("Annuler",null).setPositiveButton("Valider",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{collect.run();apply.apply(copy);dialog.dismiss();}catch(Exception e){error(a,e);}}));dialog.show();
    }catch(Exception e){error(a,e);}}
    private static long audioOffset(JSONObject p,String id)throws Exception{long at=0;JSONArray a=p.optJSONArray("audio");if(a!=null)for(int i=0;i<a.length();i++){JSONObject c=a.getJSONObject(i);if(id.equals(c.optString("clip_id")))return c.optLong("offset_ms",at);at=c.optLong("offset_ms",at)+c.optLong("duration_ms");}return 0;}
    private static void keyframes(Activity a,JSONObject target){try{JSONArray points=target.optJSONArray("gain_keyframes");if(points==null){points=new JSONArray();target.put("gain_keyframes",points);}final JSONArray values=points;List<String> rows=new ArrayList<>();for(int i=0;i<values.length();i++){JSONObject k=values.getJSONObject(i);rows.add(k.getLong("time_ms")+" ms · "+k.getDouble("volume")*100+" %");}rows.add("＋ Ajouter un point");new AgentDialog.Builder(a).setTitle("Automatisation du gain").setItems(rows.toArray(new String[0]),(d,index)->{
            JSONObject old=values.optJSONObject(index);LinearLayout box=MobileUi.column(a);EditText time=field(a,box,"Temps en ms",old==null?"0":old.optString("time_ms")),gain=field(a,box,"Volume en %",old==null?"100":String.valueOf(old.optDouble("volume")*100));
            new AgentDialog.Builder(a).setTitle("Point de volume").setView(box).setNegativeButton("Annuler",null).setNeutralButton("Supprimer",(x,w)->{if(index<values.length())values.remove(index);}).setPositiveButton("Enregistrer",(x,w)->{try{JSONObject point=new JSONObject().put("time_ms",Math.round(value(time))).put("volume",value(gain)/100);if(index<values.length())values.put(index,point);else values.put(point);List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<values.length();i++)sorted.add(values.getJSONObject(i));Collections.sort(sorted,(l,r)->Long.compare(l.optLong("time_ms"),r.optLong("time_ms")));while(values.length()>0)values.remove(0);for(JSONObject k:sorted)values.put(k);}catch(Exception e){error(a,e);}}).show();}).show();}catch(Exception e){error(a,e);}}
    static void ducking(Activity a,JSONObject project,StudioCropSheet.Apply apply){try{
        JSONObject copy=new JSONObject(project.toString());copy.put("audio_mix_version",2);JSONObject d=copy.optJSONObject("audio_ducking");if(d==null){d=new JSONObject();copy.put("audio_ducking",d);}final JSONObject duck=d;LinearLayout box=MobileUi.column(a);CheckBox enabled=check(a,box,"Activer le ducking vocal",d.optBoolean("enabled"));EditText reduction=field(a,box,"Atténuation musique · dB (-60 à 0)",String.valueOf(d.optDouble("reduction_db",-12))),threshold=field(a,box,"Seuil vocal · RMS dBFS",String.valueOf(d.optDouble("threshold_db",-40))),attack=field(a,box,"Attaque anticipée · ms",String.valueOf(d.optLong("attack_ms",80))),release=field(a,box,"Relâchement · ms",String.valueOf(d.optLong("release_ms",350))),ceiling=field(a,box,"Plafond limiteur · dBFS (-12 à -0,1)",String.valueOf(copy.optDouble("limiter_ceiling_db",-1)));TextView state=MobileUi.text(a,"Régions vocales : "+(d.optJSONArray("voice_regions")==null?0:d.optJSONArray("voice_regions").length()),13,MobileUi.TEXT);box.addView(state);
        java.util.concurrent.atomic.AtomicBoolean running=new java.util.concurrent.atomic.AtomicBoolean();Button analyze=new Button(a);analyze.setText("Détecter les paroles · Vosk local français");box.addView(analyze);analyze.setOnClickListener(v->{if(!running.compareAndSet(false,true))return;analyze.setEnabled(false);state.setText("Analyse vocale locale en cours…");WorkspaceCommands.IO.execute(()->{try{JSONArray regions=StudioAudioAnalysis.voices(a,copy,"fr",null);WorkspaceCommands.UI.post(()->{try{duck.put("voice_regions",regions).put("detector","vosk_local_word_timestamps");state.setText(regions.length()+" régions vocales reconnues · à vérifier");}catch(Exception e){error(a,e);}running.set(false);analyze.setEnabled(true);});}catch(Exception e){WorkspaceCommands.UI.post(()->{running.set(false);analyze.setEnabled(true);state.setText("Analyse échouée : "+e.getMessage());});}});});
        AlertDialog dialog=new AgentDialog.Builder(a).setTitle("Ducking et limiteur de sortie").setView(box).setNegativeButton("Annuler",null).setPositiveButton("Valider",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{try{if(running.get())throw new Exception("Attendre l'analyse vocale");duck.put("enabled",enabled.isChecked()).put("reduction_db",value(reduction)).put("threshold_db",value(threshold)).put("attack_ms",value(attack)).put("release_ms",value(release));if(enabled.isChecked()&&!duck.has("voice_regions"))throw new Exception("Détecter les paroles avant d'activer le ducking");copy.put("limiter_ceiling_db",value(ceiling));StudioMix.validate(copy);apply.apply(copy);dialog.dismiss();}catch(Exception e){error(a,e);}}));dialog.show();
    }catch(Exception e){error(a,e);}}
    private static void listen(Activity a,JSONObject p){StudioRenderPreview render=new StudioRenderPreview(a);Toast.makeText(a,"Préparation du mixage rendu…",Toast.LENGTH_SHORT).show();render.start(p,new StudioRenderPreview.Result(){public void failed(String e){Toast.makeText(a,e,Toast.LENGTH_LONG).show();}public void ready(java.io.File file){if(a.isFinishing()){render.cancel();return;}Dialog d=new Dialog(a);android.widget.VideoView video=new android.widget.VideoView(a);video.setVideoPath(file.getAbsolutePath());video.setMediaController(new MediaController(a));d.setContentView(video);d.setOnDismissListener(x->{video.stopPlayback();render.cancel();});d.show();d.getWindow().setLayout(-1,-1);video.start();}});}
    private static EditText field(Activity a,LinearLayout box,String label,String text){EditText e=fieldText(a,box,label,text);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);return e;}
    private static EditText fieldText(Activity a,LinearLayout box,String label,String text){box.addView(MobileUi.text(a,label,13,MobileUi.MUTED));EditText e=new EditText(a);e.setTextColor(MobileUi.TEXT);e.setText(text);e.setContentDescription(label);box.addView(e);return e;}
    private static CheckBox check(Activity a,LinearLayout box,String label,boolean value){CheckBox c=new CheckBox(a);c.setText(label);c.setTextColor(MobileUi.TEXT);c.setChecked(value);box.addView(c);return c;}
    private static double value(EditText e){return Double.parseDouble(e.getText().toString().trim().replace(',','.'));}
    private static void error(Activity a,Exception e){Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show();}
}
